package com.bte.service;
import com.bte.entity.*;
import com.bte.repository.*;
import com.bte.enums.*;
import com.bte.exception.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.core.Authentication;
import java.util.*;

@Service @RequiredArgsConstructor
public class TournamentRoundService {
 private final TournamentRepository tournaments;private final TournamentRoundRepository rounds;private final RegistrationRepository registrations;private final TournamentAccessService access;
 public record RoundView(int number,String mapName,String status,String roomId,String roomPassword,java.time.LocalDateTime startedAt,java.time.LocalDateTime completedAt){}
 public void configure(Tournament t,List<String> maps){if(maps==null || maps.isEmpty() || maps.size()>20 || maps.stream().anyMatch(s->s==null || s.isBlank() || s.length()>100))throw new BadRequestException("Configure 1–20 named rounds");if(t.getPlannedRounds()>0)rounds.deleteAll(rounds.findByTournamentIdOrderByRoundNumberAsc(t.getId()));rounds.flush();int n=1;for(String map:maps){var r=new TournamentRound();r.setTournament(t);r.setRoundNumber(n++);r.setMapName(map.trim());rounds.save(r);}t.setPlannedRounds(maps.size());}
 private Tournament managed(Long id,Authentication auth){var t=tournaments.findByIdForUpdate(id).orElseThrow(()->new ResourceNotFoundException("Tournament not found"));if(!access.manages(t,auth))throw new org.springframework.security.access.AccessDeniedException("Only the organizer or admin may manage rounds");if(t.isArchived())throw new BadRequestException("Archived room cannot be operated");return t;}
 @Transactional public void plan(Long id,List<String> maps,Authentication auth){var t=managed(id,auth);if(t.getStatus()!=TournamentStatus.UPCOMING || !t.getStartTime().isAfter(java.time.LocalDateTime.now()) || registrations.countByTournamentId(id)>0)throw new BadRequestException("Round plan locks after registration or tournament start");configure(t,maps);}
 @Transactional(readOnly=true) public List<RoundView> list(Long id,Authentication auth,boolean management,String ticket){var t=tournaments.findById(id).orElseThrow();if(management){if(!access.manages(t,auth))throw new org.springframework.security.access.AccessDeniedException("Organizer access required");}else access.requireAccess(t,auth,ticket);return rounds.findByTournamentIdOrderByRoundNumberAsc(id).stream().map(r->new RoundView(r.getRoundNumber(),r.getMapName(),r.getStatus(),management?r.getRoomId():null,management?r.getRoomPassword():null,r.getStartedAt(),r.getCompletedAt())).toList();}
 @Transactional public void credentials(Long id,int number,com.bte.dto.RoomCredentialsRequest body,Authentication auth){var t=managed(id,auth);if(t.getStatus()==TournamentStatus.COMPLETED || t.getStatus()==TournamentStatus.CANCELLED)throw new BadRequestException("Tournament has closed");var r=rounds.findByTournamentIdAndRoundNumber(id,number).orElseThrow(()->new ResourceNotFoundException("Round not found"));if(r.getStatus().equals("SCORED"))throw new BadRequestException("Completed round credentials are locked");r.setRoomId(body.roomId());r.setRoomPassword(body.roomPassword());if(r.getStatus().equals("LIVE")){t.setRoomId(body.roomId());t.setRoomPassword(body.roomPassword());}}
 @Transactional public void start(Long id,int number,Authentication auth){var t=managed(id,auth);if(t.getStatus()!=TournamentStatus.UPCOMING && t.getStatus()!=TournamentStatus.LIVE)throw new BadRequestException("Tournament is not available for a new round");if(t.getStartTime().isAfter(java.time.LocalDateTime.now()))throw new BadRequestException("Tournament start time has not arrived");var all=rounds.findByTournamentIdOrderByRoundNumberAsc(id);var r=all.stream().filter(x->x.getRoundNumber()==number).findFirst().orElseThrow(()->new ResourceNotFoundException("Round not found"));if(!r.getStatus().equals("SCHEDULED") || all.stream().anyMatch(x->x.getStatus().equals("LIVE") || (x.getRoundNumber()<number && !x.getStatus().equals("SCORED"))))throw new BadRequestException("Execute rounds sequentially and submit the previous result first");if(r.getRoomId()==null || r.getRoomPassword()==null)throw new BadRequestException("Publish round room ID and password first");if(registrations.findByTournamentId(id).stream().anyMatch(x->x.getPaymentStatus()==PaymentStatus.PAID && x.getSquadMembers().size()!=t.getSquadSize()))throw new BadRequestException("Complete every paid squad roster before starting");if(registrations.findByTournamentId(id).stream().noneMatch(x->x.getPaymentStatus()==PaymentStatus.PAID))throw new BadRequestException("A paid team is required to start");t.setRegistrationOpen(false);t.setStatus(TournamentStatus.LIVE);t.setRoomId(r.getRoomId());t.setRoomPassword(r.getRoomPassword());r.setStatus("LIVE");r.setStartedAt(java.time.LocalDateTime.now());}
 @Transactional public void registration(Long id,boolean open,Authentication auth){var t=managed(id,auth);if(t.getStatus()!=TournamentStatus.UPCOMING || !t.getStartTime().isAfter(java.time.LocalDateTime.now()))throw new BadRequestException("Registration cannot reopen after tournament start");t.setRegistrationOpen(open);}
 public void beforeSubmit(Tournament t,int number){if(t.getPlannedRounds()==0)return;var r=rounds.findByTournamentIdAndRoundNumber(t.getId(),number).orElseThrow(()->new BadRequestException("Match number is not configured"));if(!r.getStatus().equals("LIVE"))throw new BadRequestException("Start this round before submitting scores");}
 public void scored(Tournament t,int number){if(t.getPlannedRounds()==0){t.setStatus(TournamentStatus.UNDER_REVIEW);return;}var r=rounds.findByTournamentIdAndRoundNumber(t.getId(),number).orElseThrow();r.setStatus("SCORED");r.setCompletedAt(java.time.LocalDateTime.now());boolean done=rounds.findByTournamentIdOrderByRoundNumberAsc(t.getId()).stream().allMatch(x->x.getStatus().equals("SCORED"));t.setStatus(done?TournamentStatus.UNDER_REVIEW:TournamentStatus.LIVE);}
}
